"""Pack local quaternion motion for standalone playback, not the EAGL loader."""
import hashlib
import json
import struct
import numpy as np
from inspect_assets import ROOT


def topology(bones):
    order=[];active=set();done=set()
    def visit(i):
        if i in done:return
        if i in active:raise ValueError('Bone cycle')
        active.add(i);parent=bones[i]['parent']
        if parent>=len(bones):raise ValueError('Invalid parent')
        if parent>=0:visit(parent)
        active.remove(i);done.add(i);order.append(i)
    for i in range(len(bones)):visit(i)
    return np.array(order,dtype=int)


def quaternion(matrix):
    # Eigenvector form is stable near a half-turn; the player uses a separate formula.
    m=matrix
    k=np.array([[m[0,0]-m[1,1]-m[2,2],m[1,0]+m[0,1],m[2,0]+m[0,2],m[2,1]-m[1,2]],
                [m[1,0]+m[0,1],m[1,1]-m[0,0]-m[2,2],m[2,1]+m[1,2],m[0,2]-m[2,0]],
                [m[2,0]+m[0,2],m[2,1]+m[1,2],m[2,2]-m[0,0]-m[1,1],m[1,0]-m[0,1]],
                [m[2,1]-m[1,2],m[0,2]-m[2,0],m[1,0]-m[0,1],np.trace(m)]])
    _,vectors=np.linalg.eigh(k);q=vectors[:,-1]
    return q if q[3]>=0 else -q


def pack(clips_directory=None):
    manifest=ROOT/'modding/runtime/kitasan.json'
    current=json.loads(manifest.read_text()) if manifest.exists() else {}
    clips_directory=clips_directory or ROOT/current.get('reference_clip_directory','modding/animation-offline-v2')
    clips_directory.resolve().relative_to((ROOT/'modding').resolve())
    folder=ROOT/'modding/character-source';mesh=(folder/'mesh.bin').read_bytes()
    nv,ni=struct.unpack_from('<II',mesh);skin=(folder/'skin.bin').read_bytes()
    bones=json.loads((folder/'skeleton.json').read_text());nb=len(bones)
    if len(mesh)!=8+nv*36+ni*4 or len(skin)!=nv*24:raise ValueError('Source size mismatch')
    ids=np.frombuffer(mesh,'<u4',ni,8+nv*36)
    if ids.max()>=nv or nv>65535 or ni%3:raise ValueError('Invalid triangle indices')
    records=np.frombuffer(mesh,'u1',nv*36,8).reshape(nv,36).copy()
    colors=records[:,32:36].copy();uv=records[:,24:32].copy()
    records[:,24:28]=colors[:,[2,1,0,3]];records[:,28:36]=uv
    order=topology(bones);remap=np.empty(nb,dtype='<u2');remap[order]=np.arange(nb)
    rest=np.array([b['position'] for b in bones]);skeleton=bytearray()
    for i in order:
        parent=bones[i]['parent'];parent=int(remap[parent]) if parent>=0 else -1
        skeleton.extend(struct.pack('<hH3f',parent,0,*rest[i]))
    skin_out=bytearray(skin)
    for i in range(nv):
        old=struct.unpack_from('<4H',skin,i*24)
        if max(old)>=nb:raise ValueError('Invalid skin index')
        struct.pack_into('<4H',skin_out,i*24,*(int(remap[j]) for j in old))
    clips=[];counts=[]
    for name in ('idle','run'):
        with np.load(clips_directory/f'{name}.npz',allow_pickle=False) as clip:
            r=clip['rotations'].astype(float);t=clip['offsets'].astype(float)
            if r.ndim!=4 or r.shape[1:]!=(nb,3,3) or t.shape!=r.shape[:2]+(3,) or not np.isfinite(r).all() or not np.isfinite(t).all():raise ValueError('Invalid motion arrays')
            positions=np.einsum('fbij,bj->fbi',r,rest)+t
            local=np.empty((len(r),nb,7),dtype='<f4')
            for frame in range(len(r)):
                for destination,i in enumerate(order):
                    parent=bones[i]['parent']
                    if parent<0:rotation=r[frame,i];translation=positions[frame,i]-rest[i]
                    else:
                        rotation=r[frame,parent].T@r[frame,i]
                        translation=r[frame,parent].T@(positions[frame,i]-positions[frame,parent])-(rest[i]-rest[parent])
                    left,_,right=np.linalg.svd(rotation);rotation=left@right
                    if np.linalg.det(rotation)<0:raise ValueError('Reflected bone rotation')
                    translation[np.abs(translation)<2e-6]=0
                    local[frame,destination,:4]=quaternion(rotation);local[frame,destination,4:]=translation
            counts.append(len(r));clips.append(local.tobytes())
    indexbytes=ids.astype('<u2').tobytes();padding=b'\0'*((-len(indexbytes))%4)
    header=struct.pack('<4s7I',b'UMAB',2,nv,ni,nb,*counts,0)
    return header+records.tobytes()+bytes(skin_out)+bytes(skeleton)+indexbytes+padding+b''.join(clips)


def main():
    data=pack();output=ROOT/'modding/runtime/kitasan.umab'
    # This is generated authoring data, never an installed game resource.
    output.write_bytes(data)
    report={'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest(),'format':'UMAB v2; local quaternions, translations and parent hierarchy; not an EAGL container','game_integrated':False,'reference_clip_directory':json.loads(output.with_suffix('.json').read_text()).get('reference_clip_directory','modding/animation-offline-v2')}
    output.with_suffix('.json').write_text(json.dumps(report,indent=2)+'\n')
    print(json.dumps(report))

if __name__=='__main__':main()

"""Compute accurate character submesh bounds in memory; never write game data."""
import hashlib
import math
import struct
from inspect_assets import chunks, data_path, flatten, save_json
from extract_assets import geometry,payload


def bounds_preview(data):
    meshes=geometry(data,'_KIT00_BODY_')
    targets={f'COROLLA_KIT00_BODY_{lod}'for lod in 'ABCD'}
    if {m['name'] for m in meshes}!=targets:raise ValueError('Unexpected character body set')
    nodes={n['offset']:n for n in flatten(chunks(data))}
    result=bytearray(data);changes=[]
    for mesh in meshes:
        solid=nodes[mesh['solid_offset']]
        ranges=next(n for n in flatten(solid['children']) if n['id']=='0x00134b02')
        raw=payload(data,ranges);lead=len(raw)%60
        if struct.unpack_from('<II',raw,lead+48)[1]!=0 or struct.unpack_from('<I',raw,lead+12)[0]!=len(mesh['indices']):
            raise ValueError('Expected first range to cover the entire character')
        referenced=[mesh['positions'][i] for i in set(mesh['indices'])]
        old_min=struct.unpack_from('<3f',raw,lead);old_max=struct.unpack_from('<3f',raw,lead+16)
        if all(old_min[k]<=p[k]<=old_max[k] for p in referenced for k in range(3)):
            raise ValueError('Bounds already contain the character')
        fields=[]
        for at,lower in ((0,True),(16,False)):
            for axis in range(3):
                value=(min if lower else max)(p[axis] for p in referenced)+(-0.01 if lower else 0.01)
                if not math.isfinite(value):raise ValueError('Invalid character bounds')
                offset=ranges['payload']+lead+at+axis*4
                old=data[offset:offset+4];new=struct.pack('<f',value)
                result[offset:offset+4]=new
                fields.append({'offset':offset,'offset_hex':hex(offset),'old_hex':old.hex(' '),'new_hex':new.hex(' '),'new_value':struct.unpack('<f',new)[0]})
        changes.append({'part':mesh['name'],'old_min':old_min,'old_max':old_max,'fields':fields})
    if len(result)!=len(data) or chunks(data)!=chunks(result):raise ValueError('Unexpected structural change')
    return bytes(result),changes


def main():
    relative='CARS/COROLLA/GEOMETRY.BIN';data=data_path(relative).read_bytes();result,changes=bounds_preview(data)
    count=sum(a!=b for a,b in zip(data,result))
    plan={'source':relative,'source_sha256':hashlib.sha256(data).hexdigest(),'result_sha256':hashlib.sha256(result).hexdigest(),
          'bytes_before':len(data),'bytes_after':len(result),'field_bytes':96,'changed_bytes':count,'changes':changes,
          'backup':relative+'.before-bounds.bak','temporary':relative+'.uma-bounds.tmp','approval_required':True,
          'purpose':'Repair first material range AABBs that do not contain the actual character geometry',
          'limits':'Does not prove race visibility, alter pose, animate the character, remove wheels, or change materials'}
    save_json('bounds-repair-plan.json',plan)
    print(f'IN MEMORY: 24 float fields, {count} changed bytes; size unchanged {len(data)}')
    for change in changes:print(change['part'],'old bounds',change['old_min'],change['old_max'],'field offsets',[f['offset_hex'] for f in change['fields']])

if __name__=='__main__':main()

"""Build a geometry candidate in memory and save only a review report, never game bytes."""
import hashlib
import struct
import subprocess
from inspect_assets import ROOT,chunks,flatten,data_path,save_json
from extract_assets import geometry,payload

SOURCE_HASH='cedf717c16c342b449c32e312351bd2f93d21533446b9501488dd0b5a3664389'

def reviewed_source():
    for relative in ('CARS/COROLLA/GEOMETRY.BIN','CARS/COROLLA/GEOMETRY.BIN.before-runtime.bak'):
        path=data_path(relative)
        if path.exists() and hashlib.sha256(path.read_bytes()).hexdigest()==SOURCE_HASH:return path
    raise ValueError('Reviewed prototype source or exact backup required')

def verify_compaction(original,raw):
    oldtree=chunks(original);newtree=chunks(raw)
    oldmeshes={m['asset_hash']:m for m in geometry(original,'COROLLA_')}
    newmeshes={m['asset_hash']:m for m in geometry(raw,'COROLLA_')}
    if oldmeshes.keys()!=newmeshes.keys():raise ValueError('Part names changed')
    oldnodes={n['offset']:n for n in flatten(oldtree)}
    newnodes={n['offset']:n for n in flatten(newtree)}
    edited_ids={'0x00134011','0x00134900','0x00134b01','0x00134b02','0x00134b03'}
    changes=[]
    for name,old in oldmeshes.items():
        new=newmeshes[name]
        if old['name']!=new['name']:raise ValueError('Display name changed')
        oldsolid=oldnodes[old['solid_offset']];newsolid=newnodes[new['solid_offset']]
        oldleaves=[n for n in flatten(oldsolid.get('children',[])) if not n.get('children') and n['id'] not in edited_ids and n['id']!='0x00000000']
        newleaves=[n for n in flatten(newsolid.get('children',[])) if not n.get('children') and n['id'] not in edited_ids and n['id']!='0x00000000']
        if len(oldleaves)!=len(newleaves):raise ValueError('Unknown leaf set changed')
        for before,after in zip(oldleaves,newleaves):
            if before['id']!=after['id'] or payload(original,before)!=payload(raw,after):raise ValueError('Opaque solid data changed')
        collapsed=all(all(v==0 for v in p) for p in old['positions'])
        if collapsed:
            if len(new['positions'])!=3 or len(new['indices'])!=3 or any(any(v!=0 for v in p) for p in new['positions']):raise ValueError(f'Invalid compact degenerate mesh: {name}; {len(new["positions"])} vertices, {len(new["indices"])} indices')
            changes.append({'asset_hash':name,'part':old['name'],'old_offset':old['solid_offset'],'new_offset':new['solid_offset'],'vertices_before':len(old['positions']),'vertices_after':3,'triangles_before':len(old['indices'])//3,'triangles_after':1})
        else:
            before=old['vertex_data_offset'];after=new['vertex_data_offset'];length=len(old['positions'])*old['stride']
            if original[before:before+length]!=raw[after:after+length]:raise ValueError('Visible vertex records changed')
            for key in ('positions','normals','uv','indices','markers','transform','material_runs'):
                if old[key]!=new[key]:raise ValueError(f'Visible mesh changed: {name}/{key}')
        if old['markers']!=new['markers'] or old['transform']!=new['transform']:raise ValueError('Anchors changed')
    records_checked=0
    for n in flatten(newtree):
        if n['id']=='0x80134010' and n['offset']%128:raise ValueError('Solid alignment')
        if n['id']=='0x00134004':
            records=payload(raw,n)
            if len(records)%24:raise ValueError('Partial solid directory')
            for at in range(0,len(records),24):
                key,offset,size1,size2,a,b=struct.unpack_from('<6I',records,at)
                if a or b or size1!=size2 or offset+size1>len(raw):raise ValueError('Invalid directory record')
                tag,size=struct.unpack_from('<2I',raw,offset)
                if tag!=0x80134010 or size+8!=size1:raise ValueError('Directory relocation failed')
                solid_header=next(x for x in flatten(chunks(raw,offset,offset+size1)) if x['id']=='0x00134011')
                if struct.unpack_from('<I',raw,solid_header['payload']+16)[0]!=key:raise ValueError('Directory identity mismatch')
                records_checked+=1
    if records_checked!=len(oldmeshes):raise ValueError('Solid directory count mismatch')
    info=next(n for n in flatten(newtree) if n['id']=='0x00134002')
    off,size=struct.unpack_from('<2I',raw,info['payload']+104)
    if off%64 or off+size>len(raw) or struct.unpack_from('<2I',raw,off)!=(0x80034020,size-8):raise ValueError('Collision relocation failed')
    oldcol=next(n for n in oldtree if n['id']=='0x80034020')
    if payload(original,oldcol)!=raw[off+8:off+size]:raise ValueError('Collision payload changed')
    return {'source':'CARS/COROLLA/GEOMETRY.BIN','source_sha256':hashlib.sha256(original).hexdigest(),'result_sha256':hashlib.sha256(raw).hexdigest(),'bytes_before':len(original),'bytes_after':len(raw),'collapsed_solids_compacted':len(changes),'vertices_before':sum(len(m['positions']) for m in oldmeshes.values()),'vertices_after':sum(len(m['positions']) for m in newmeshes.values()),'solid_directory_records_verified':records_checked,'collision_pointer_before':oldcol['offset'],'collision_pointer_after':off,'collision_payload_unchanged':True,'noncollapsed_geometry_unchanged':True,'visible_vertex_records_unchanged':True,'other_solid_leaf_payloads_unchanged':True,'part_names_markers_transforms_preserved':True,'installed':False,'binary_saved':False,'approval_required':True,'limits':'Does not prove race visibility or fix body-kit selection, material bounds, running integration or residual shared wheels. Diagnostic candidate only.','changes':changes}

def main():
    source=reviewed_source();original=source.read_bytes()
    if hashlib.sha256(original).hexdigest()!=SOURCE_HASH:raise ValueError('Expected reviewed prototype source')
    build=subprocess.run([str(ROOT/'modding/runtime/compact-hidden-dry-run'),str(source.relative_to(ROOT))],cwd=ROOT,stdout=subprocess.PIPE,check=True,timeout=120)
    report=verify_compaction(original,build.stdout)
    if source.read_bytes()!=original:raise ValueError('Source changed during planning')
    save_json('hidden-compaction-plan.json',report)
    print({k:v for k,v in report.items() if k!='changes'})

if __name__=='__main__':main()
